from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
ws = wb['ورقة1']

# Read data from A2:E8
data = []
for row in ws.iter_rows(min_row=2, max_row=8, min_col=1, max_col=5):
    row_data = [cell.value for cell in row]
    data.append(row_data)

# Process the data
brand_data = {}
for entry in data:
    date, brand, batch, origin, quantity = entry
    if brand not in brand_data:
        brand_data[brand] = {
            'date': date,
            'batch': batch,
            'origin': origin,
            'quantity': quantity
        }
    else:
        # Compare dates and keep the most recent one
        if date > brand_data[brand]['date']:
            brand_data[brand] = {
                'date': date,
                'batch': batch,
                'origin': origin,
                'quantity': quantity
            }
        elif date == brand_data[brand]['date']:
            # If same date, sum the quantities
            brand_data[brand]['quantity'] += quantity

# Prepare the result
result = []
for brand, info in brand_data.items():
    result.append([info['date'], brand, info['batch'], info['origin'], info['quantity']])

# Write the result to H2:L4
for i, row in enumerate(result):
    for j, value in enumerate(row):
        ws[f'H{i+2}'] = value

# Save the workbook
wb.save('output.xlsx')
