ws_zord = wb['ZORD']

# Function to format date as DD/MM/YYYY
def format_date(date):
    if isinstance(date, datetime):
        return date.strftime('%d/%m/%Y')
    return str(date)

# Process each row in the Volym sheet
for row in ws_volym.iter_rows(min_row=2, max_row=10, min_col=9, max_col=9):
