        if zord_material == material:
            # Check if the current row's Quota is "Yes"
            if ws_volym.cell(row=row[0].row, column=2).value == "Yes":
                # Check if the current date is within the valid_from and valid_to range
                if valid_from <= ws_volym.cell(row=row[0].row, column=3).value <= valid_to:
                    dates.append(format_date(valid_from))

    # Join the dates with a comma delimiter
    if dates:
