from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Dictionary to store the sum and count of turnaround times for each department
department_data = {}

# Iterate through the rows in the data
for row in ws.iter_rows(min_row=2, max_row=13, values_only=True):
    department, status, turnaround_time = row
    if department and status in ["In Progress", "In Review"] and turnaround_time >= 6:
        if department not in department_data:
            department_data[department] = {'sum': 0, 'count': 0}
        department_data[department]['sum'] += turnaround_time
        department_data[department]['count'] += 1

# Write the results to the answer range
for i, row in enumerate(ws.iter_rows(min_row=11, max_row=13, values_only=True)):
    department = row[0]
    if department in department_data and department_data[department]['count'] > 0:
        average = department_data[department]['sum'] / department_data[department]['count']
        ws.cell(row=11 + i, column=2, value=average)
    else:
        ws.cell(row=11 + i, column=2, value='')

# Save the workbook
wb.save('output.xlsx')
